import { useState, useRef } from 'react';
import { useAdminContext } from '@/context/AdminContext';
import { useAdminMutations } from '@/hooks/useAdminMutations';
import { getInvestigationRequestLabel } from '@/types';
import EntityList from '../Shared/EntityList';
import type { Level, Phase } from '@/types';

interface InvRequest {
  id: number;
  request_type: string;
}

export default function LevelForm() {
  const [editingId, setEditingId] = useState(null);

  const [title, setTitle] = useState('');
  const [details, setDetails] = useState('');
  const [orderIndex, setOrderIndex] = useState('1');
  const [image, setImage] = useState(null);
  const [storeLocally, setStoreLocally] = useState(false);
  const [isInitial, setIsInitial] = useState(true);
  const [presentationType, setPresentationType] = useState('interrogation');
  const [requiredRequestId, setRequiredRequestId] = useState('');
  const fileInputRef = useRef(null);

  // setPhaseId is kept because editing a level updates the active phase in Context
  const { caseId, phaseId, setPhaseId, selectedCase, selectedPhase, availablePhases } = useAdminContext();

  const {
    createEntity, updateEntity, deleteEntity, isProcessing,
    feedback, clearFeedback
  } = useAdminMutations('level');

  if (!caseId || !phaseId || !selectedCase || !selectedPhase) {
    return (



[ MISSING CONTEXT: TARGET PHASE REQUIRED ]

Please select a Case and a Phase from the sidebar to manage Levels.

    );
  }

  const clearForm = () => {
    setEditingId(null);
    setTitle(''); setDetails(''); setOrderIndex('1');
    setIsInitial(true); setStoreLocally(false); setPresentationType('standard');
    setRequiredRequestId(''); setImage(null);
    clearFeedback();
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const availableRequests = (selectedCase as any)?.investigation_requests as InvRequest[] || [];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    clearFeedback();

    const formData = new FormData();
    formData.append('phase_id', phaseId); formData.append('title', title);
    formData.append('details', details); formData.append('order_index', orderIndex);
    formData.append('is_initial', isInitial ? '1' : '0');
    formData.append('presentation_type', presentationType);
    formData.append('store_locally', storeLocally ? '1' : '0');
    if (requiredRequestId) formData.append('required_request_id', requiredRequestId);
    if (image) formData.append('image', image);

    if (editingId) {
      updateEntity({ id: editingId, formData }, { onSuccess: clearForm });
    } else {
      createEntity(formData, { onSuccess: clearForm });
      setOrderIndex((prev) => (parseInt(prev || '1') + 1).toString());
    }
  };

  const handleEdit = (level: Level, parentPhaseId: number) => {
    setPhaseId(parentPhaseId.toString());
    setEditingId(level.id);
    setTitle(level.title);
    setDetails(level.details || '');
    setOrderIndex(level.order_index.toString());
    setIsInitial(!!level.is_initial);
    setPresentationType(level.presentation_type || 'standard');

    const reqId = (level as any).required_request_id;
    setRequiredRequestId(reqId ? reqId.toString() : '');

    setImage(null);
    clearFeedback();
    if (fileInputRef.current) fileInputRef.current.value = '';
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (level: Level) => {
    if (window.confirm(`Are you absolutely sure you want to delete "${level.title}"? All nested questions and media will be wiped permanently.`)) {
      if (editingId === level.id) clearForm();
      deleteEntity(level.id);
    }
  };

  return (











              {editingId ? `// Editing Level ID: ${editingId}` : '// Initialize New Level'}


              Targeting: {selectedCase.title} > {selectedPhase.title}


          {editingId && (

              Cancel Edit

          )}


        {feedback && 
{feedback.message}}






              Phase Order Index
               setOrderIndex(e.target.value)} />




              Presentation Format
               setPresentationType(e.target.value)}>
                Suspect Interrogation
                Location
                Communications Wiretap





              Required Combo (Gatekeeper)
               setRequiredRequestId(e.target.value)}>
                -- No Requirement --
                {availableRequests.map((req) => (

                    REQ-{req.id}: {getInvestigationRequestLabel(req.request_type)}

                ))}






             setIsInitial(e.target.checked)} style={{ transform: 'scale(1.5)', accentColor: 'var(--accent-cyan)' }} />

              Initial Phase: This phase is visible on the roadmap immediately. (Uncheck if it must be unlocked via a specific player choice).





            Level Title
             setTitle(e.target.value)} />




            Level Details (Objectives)
             setDetails(e.target.value)} />




            Location / Background Image {editingId && '(Leave blank to keep existing)'}


              Optimal: 16:9 ratio (e.g., 1920x1080) for full-screen location sweeps. High contrast recommended. Max 4MB.

             setImage(e.target.files?.[0] || null)} />




             setStoreLocally(e.target.checked)} style={{ transform: 'scale(1.3)', accentColor: 'var(--accent-amber)' }} />

              Store Locally on Server: Save assets directly to public server folders instead of Cloudinary.




            {isProcessing ? 'Processing Data...' : editingId ? 'Update Level' : 'Commit Level to Database'}




      {availablePhases.length > 0 && (


          {availablePhases.map((phase: Phase) => (
            <EntityList
              key={`phase-group-${phase.id}`}
              title={`Levels in Phase: ${phase.title}`}
              items={[...(phase.levels || [])].sort((a, b) => a.order_index - b.order_index)}
              emptyMessage="No levels assigned to this phase."
              keyExtractor={(level) => level.id}
              isProcessing={isProcessing}
              onEdit={(level) => handleEdit(level, phase.id)}
              onDelete={handleDelete}
              renderItemContent={(level) => (
                <>
                  IDX: {level.order_index}
                  {level.title}
                  ({level.presentation_type})
                </>
              )}
            />
          ))}

      )}

  );
}

import { useState } from 'react';
import { useAdminContext } from '@/context/AdminContext';
import { useAdminMutations } from '@/hooks/useAdminMutations';
import type { Evidence } from '@/types/evidence';
import type { Question, Choice, Level, Suspect, Victim } from '@/types';
import { type DraftChoice } from '../Shared/ChoiceEditorCard';
import { defaultRequirements, defaultOutcomes, buildNodeFormData } from '../Shared/questionUtils';
import AdminInterrogationForm from './AdminInterrogationForm';
import './AdminInterrogationBuilder.css';

interface DialogueNodeContainerProps {
  nodeData: Question | any;
  levelId: string;
  allSavedNodes: Question[];
  availableEvidences: Evidence[];
  availableLevels: Level[];
  availableSuspects: Suspect[];
  availableVictims: Victim[];
  onSaved: () => void;
  onDeleted: () => void;
}

const DialogueNodeContainer = ({
  nodeData, levelId, allSavedNodes, availableEvidences, availableLevels, availableSuspects, availableVictims, onSaved, onDeleted
}: DialogueNodeContainerProps) => {

  // SECURE MAPPER: Forces all ID arrays to be Number[] to satisfy TS
  const safeChoices: DraftChoice[] = (nodeData.choices || []).map((c: Choice | any) => ({
    id: c.id || crypto.randomUUID(),
    text: c.text || '',
    outcomes: {
      feedback: c.outcomes?.feedback || '',
      next_question_id: c.outcomes?.next_question_id ? Number(c.outcomes.next_question_id) : null,
      gives_strike: !!c.outcomes?.gives_strike,
      unlock_evidence: c.outcomes?.unlock_evidence?.map(Number) || [],
      unlock_levels: c.outcomes?.unlock_levels?.map(Number) || [],
      unlock_suspects: c.outcomes?.unlock_suspects?.map(Number) || [],
      unlock_victims: c.outcomes?.unlock_victims?.map(Number) || []
    },
    requirements: {
      required_evidence: c.requirements?.required_evidence?.map(Number) || [],
      required_choices: c.requirements?.required_choices?.map(Number) || []
    }
  }));

  const [text, setText] = useState(nodeData.text || '');
  const [choices, setChoices] = useState(safeChoices.length > 0 ? safeChoices : [
    { id: crypto.randomUUID(), text: '', outcomes: defaultOutcomes(), requirements: defaultRequirements() }
  ]);
  const [showAdvanced, setShowAdvanced] = useState<Record>({});

  const isSaved = typeof nodeData.id === 'number';

  const {
    createEntity, updateEntity, deleteEntity, isProcessing,
    feedback, setFeedback, clearFeedback
  } = useAdminMutations('question');

  const handleSave = () => {
    clearFeedback();

    if (!text.trim()) return setFeedback({ type: 'error', message: 'Suspect dialogue text cannot be empty.' });
    if (choices.some(c => !c.text.trim())) return setFeedback({ type: 'error', message: 'All response branches must have text.' });

    const formData = buildNodeFormData({
      level_id: levelId,
      text,
      store_locally: false,
      choices
    });

    if (isSaved) {
      updateEntity({ id: nodeData.id, formData }, { onSuccess: onSaved });
    } else {
      createEntity(formData, { onSuccess: onSaved });
    }
  };

  const handleDelete = () => {
    if(window.confirm('Delete node?')) {
      deleteEntity(nodeData.id, { onSuccess: onDeleted });
    }
  };

  const updateChoice = (id: string, field: keyof DraftChoice | string, value: any, category?: 'outcomes' | 'requirements') => {
    setChoices(choices.map(c => {
      if (c.id !== id) return c;
      if (category) {
        return {
          ...c,
          [category]: {
            ...(c[category] || {}),
            [field]: value
          }
        };
      }
      return { ...c, [field]: value };
    }));
  };

  const addChoice = () => {
    setChoices([...choices, { id: crypto.randomUUID(), text: '', outcomes: defaultOutcomes(), requirements: defaultRequirements() }]);
  };

  const removeChoice = (id: string) => {
    setChoices(choices.filter(c => c.id !== id));
  };

  return (

  );
};

