import { useState } from 'react';
import { useAdminContext } from '@/context/AdminContext';
import type { Evidence, Level, Phase, Suspect, Victim } from '@/types';

export interface DraftChoice {
  id?: number | string;
  text: string;
  outcomes?: {
    unlock_evidence?: number[];
    unlock_levels?: number[];
    unlock_suspects?: number[];
    unlock_victims?: number[];
    next_question_id?: number | null;
    gives_strike?: boolean;
    feedback?: string;
  };
  requirements?: {
    required_evidence?: number[];
    required_choices?: number[];
  };
}

export interface LevelWithPhase extends Level {
  phase?: Phase;
  phase_title?: string;
}

export interface FlattenedChoice extends DraftChoice {
  question_id?: number;
  question_text?: string;
}

interface ChoiceEditorCardProps {
  index: number;
  choice: DraftChoice;
  updateChoice: (updated: DraftChoice) => void;
  removeChoice: () => void;
  isLocationMode?: boolean;
  isTargeting?: boolean;
  onToggleTarget?: () => void;
}

export default function ChoiceEditorCard({
  index,
  choice,
  updateChoice,
  removeChoice,
  isLocationMode = false,
  isTargeting = false,
  onToggleTarget
}: ChoiceEditorCardProps) {

  const [isExpanded, setIsExpanded] = useState(
    typeof choice.id === 'string' || choice.id === undefined
  );

  const { selectedCase } = useAdminContext();

  // Protect against rendering if context drops
  if (!selectedCase) return null;

  const availableEvidence = selectedCase.evidences || [];
  const availableLevels = selectedCase.phases?.flatMap(p => p.levels || []) || [];
  const availableSuspects = selectedCase.suspects || [];
  const availableVictims = selectedCase.victims || [];

  const updateOutcomes = <K extends keyof NonNullable>(
    key: K,
    value: NonNullable[K]
  ) => {
    updateChoice({
      ...choice,
      outcomes: {
        ...(choice.outcomes || {}),
        [key]: value
      }
    });
  };

  const updateRequirements = <K extends keyof NonNullable>(
    key: K,
    value: NonNullable[K]
  ) => {
    updateChoice({
      ...choice,
      requirements: {
        ...(choice.requirements || {}),
        [key]: value
      }
    });
  };

  const unlockedEv = choice.outcomes?.unlock_evidence?.map(String) || [];
  const unlockedLv = choice.outcomes?.unlock_levels?.map(String) || [];
  const unlockedSu = choice.outcomes?.unlock_suspects?.map(String) || [];
  const unlockedVi = choice.outcomes?.unlock_victims?.map(String) || [];
  const reqEv = choice.requirements?.required_evidence?.map(String) || [];

  const hasCoords = choice.text.includes('|') && !choice.text.startsWith('|');
  const coordPreview = hasCoords ? choice.text.split('|')[0].trim() : null;

  return (



      {/* CLEAN HEADER BAR */}

 setIsExpanded(!isExpanded)}
        style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer', userSelect: 'none' }}
      >



            Choice #{index + 1}


            {choice.text ? `"${choice.text}"` : '(Blank Choice Text)'}


          {coordPreview && (

              📍 {coordPreview}%

          )}

          {choice.outcomes?.gives_strike && (

              STRIKE PENALTY

          )}



 e.stopPropagation()}>

          {isLocationMode && onToggleTarget && (

              {isTargeting ? '🎯 TARGETING...' : '🎯 MAP'}

          )}

           setIsExpanded(!isExpanded)}
            className="btn-secondary"
            style={{ padding: '0.25rem 0.75rem', fontSize: '0.75rem', width: 'auto', background: 'rgba(255,255,255,0.05)' }}
          >
            {isExpanded ? '▲ Collapse' : '▼ Expand'}



            ✕




      {/* COLLAPSIBLE BODY CONTENT */}
      {isExpanded && (




            Choice Text
             updateChoice({ ...choice, text: e.target.value })}
              placeholder="e.g., The killer entered through the vents."
            />





[ NARRATIVE OUTCOMES & UNLOCKS ]



               updateOutcomes('gives_strike', e.target.checked)}
                style={{ transform: 'scale(1.3)', accentColor: 'var(--accent-crimson)' }}
              />

                PENALTY STRIKE: Selecting this choice logs a strike against the team.





              Feedback Message (Shown when selected / Failed hint)
               updateOutcomes('feedback', e.target.value)}
                style={{ minHeight: '60px' }}
                placeholder="e.g., You wasted time tracking a dead end."
              />






                Unlocks Evidence
                 updateOutcomes('unlock_evidence', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableEvidence.map((ev: Evidence) => (
                    EX-{ev.id.toString().padStart(3, '0')}: {ev.title}
                  ))}




                Unlocks Phase/Level
                 updateOutcomes('unlock_levels', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableLevels.map((lv: Level) => (
                    Level {lv.order_index}: {lv.title}
                  ))}








                Unlocks Suspects
                 updateOutcomes('unlock_suspects', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableSuspects.map((su: Suspect) => (
                    {su.name}
                  ))}




                Unlocks Victims
                 updateOutcomes('unlock_victims', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                  {availableVictims.map((vi: Victim) => (
                    {vi.name}
                  ))}








[ GATEKEEPER REQUIREMENTS ]


              Required Evidence to Select
               updateRequirements('required_evidence', Array.from(e.target.selectedOptions, opt => Number(opt.value)))}>
                {availableEvidence.map((ev: Evidence) => (
                  EX-{ev.id.toString().padStart(3, '0')}: {ev.title}
                ))}




      )}


  );
}

import { type ReactNode } from 'react';

interface EntityListProps {
  title: string;
  items: T[];
  emptyMessage?: string;
  keyExtractor: (item: T) => string | number;
  renderItemContent: (item: T) => ReactNode;
  onEdit: (item: T) => void;
  onDelete: (item: T) => void;
  isProcessing: boolean;
}

export default function EntityList({
  title,
  items,
  emptyMessage = 'No items found.',
  keyExtractor,
  renderItemContent,
  onEdit,
  onDelete,
  isProcessing
}: EntityListProps) {
  return (




        // {title}


      {items.length === 0 ? (


          {emptyMessage}

      ) : (


          {items.map((item) => (




                {renderItemContent(item)}



                 onEdit(item)}
                  disabled={isProcessing}
                  style={{ background: 'transparent', border: '1px solid var(--accent-amber)', color: 'var(--accent-amber)', padding: '0.5rem 1rem', borderRadius: '4px', cursor: 'pointer', fontFamily: 'var(--font-mono)' }}
                >
                  Edit

                 onDelete(item)}
                  disabled={isProcessing}
                  style={{ background: 'transparent', border: '1px solid var(--accent-crimson)', color: 'var(--accent-crimson)', padding: '0.5rem 1rem', borderRadius: '4px', cursor: 'pointer', fontFamily: 'var(--font-mono)' }}
                >
                  Delete



          ))}

      )}

  );
}

interface EvidenceMetadataFieldsProps {
  evidenceType: string;
  subType: string;
  setSubType: (val: string) => void;
  metadata: Record;
  updateMeta: (key: string, value: any) => void;
}

export default function EvidenceMetadataFields({
  evidenceType,
  subType,
  setSubType,
  metadata,
  updateMeta
}: EvidenceMetadataFieldsProps) {

  // Renders the specific sub-type dropdown based on the main category
  const renderSubTypeSelector = () => {
    if (evidenceType === 'forensic') {
      return (
         setSubType(e.target.value)}>
          -- Select Forensic Classification --
          Autopsy Report
          Ballistics Analysis
          DNA / Serology Profile
          Digital Forensics
          Trace / Material Analysis

      );
    }

    if (evidenceType === 'document') {
      return (
         setSubType(e.target.value)}>
          -- Select Document Classification --
          Correspondence (Email/Letter)
          Financial Record
          Personal Diary / Journal
          Official Contract / Deed
          Corporate Memo / Note
          Background Check / Dossier

      );
    }
    return null;
  };

  // Renders the precise form inputs required for the selected sub-type
  const renderDynamicInputs = () => {
    switch (subType) {
      // --- FORENSIC SUB-TYPES ---
      case 'autopsy':
        return (
          <>



Chief Medical Examiner updateMeta('examiner', e.target.value)} required />

Est. Time of Death updateMeta('time_of_death', e.target.value)} required />


Primary Cause of Death updateMeta('cause_of_death', e.target.value)} required />

Examiner Notes / Anomalies (Optional) updateMeta('anomalies', e.target.value)} />
          </>
        );

      case 'ballistics': {
        const exhibits = metadata.exhibits || [];

        const addExhibit = () => {
          updateMeta('exhibits', [...exhibits, { reference: '', description: '' }]);
        };

        const updateExhibit = (index: number, field: string, value: string) => {
          const newEx = [...exhibits];
          newEx[index] = { ...newEx[index], [field]: value };
          updateMeta('exhibits', newEx);
        };

        const removeExhibit = (index: number) => {
          const newEx = exhibits.filter((_: any, i: number) => i !== index);
          updateMeta('exhibits', newEx);
        };

        return (
          <>




                [ FORMATTING GUIDE ] Use HTML tags to trigger immersive effects:



<span className="redacted">Text</span> : Black redaction bar.

<span className="highlighted">Text</span> : Yellow highlighter marker.






Lab Case Number updateMeta('case_number', e.target.value)} required placeholder="e.g., 2026-BL-8842" />

Examiner Name updateMeta('examiner_name', e.target.value)} required />






                EVIDENCE INTAKE LOG (EXHIBITS)
                + Add Exhibit


              {exhibits.map((ex: any, idx: number) => (


                   updateExhibit(idx, 'reference', e.target.value)} style={{ width: '160px' }} required />
                   updateExhibit(idx, 'description', e.target.value)} style={{ flex: 1 }} required />
                   removeExhibit(idx)} style={{ background: 'transparent', border: 'none', color: 'var(--accent-crimson)', cursor: 'pointer', fontSize: '1.2rem', padding: '0 0.5rem' }} title="Remove Exhibit">×

              ))}

              {exhibits.length === 0 && (


                  No exhibits logged. Add a row above.

              )}



TECHNICAL FINDINGS

Firearm Specification Data updateMeta('firearm_specs', e.target.value)} style={{ minHeight: '60px' }} />

Microscopic & Toolmark Analysis updateMeta('microscopic_analysis', e.target.value)} style={{ minHeight: '80px' }} />

Trajectory & Range Findings (If Applicable) updateMeta('trajectory_range', e.target.value)} style={{ minHeight: '60px' }} />


Official Conclusion / Match Determination updateMeta('conclusion', e.target.value)} required style={{ minHeight: '60px', borderLeft: '3px solid var(--accent-crimson)' }} placeholder="e.g., MATCH CONFIRMED: Striation patterns on Exhibit A match..." />



              Investigator Handwritten Scrawls
               updateMeta('investigator_notes', e.target.value)} placeholder="Will render in a red cursive marker font..." style={{ minHeight: '80px' }} />

          </>
        );
      }

      case 'dna':
        return (
          <>



Sample Type (e.g., Blood, Hair) updateMeta('sample_type', e.target.value)} required />

Match Probability updateMeta('match_probability', e.target.value)} required />


Identified Subject (Leave blank if inconclusive) updateMeta('identified_person', e.target.value)} />
          </>
        );

      case 'digital_forensics':
        return (
          <>



Device Classification updateMeta('device_type', e.target.value)} required />

Extraction Method updateMeta('extraction_method', e.target.value)} required />


Decrypted Data / Payload updateMeta('recovered_data', e.target.value)} required />
          </>
        );

      case 'trace_analysis':
        return (
          <>



Material Composition updateMeta('material_type', e.target.value)} required />

Identified Origin Source updateMeta('origin_source', e.target.value)} required />

          </>
        );

      // --- DOCUMENT SUB-TYPES ---
      case 'correspondence':
        return (
          <>



Sender (FROM) updateMeta('sender', e.target.value)} required />

Recipient (TO) updateMeta('recipient', e.target.value)} required />


Subject Line updateMeta('subject', e.target.value)} required />

Message Body updateMeta('body', e.target.value)} required />
          </>
        );

      case 'financial': {
        const pages = metadata.pages || [];

        const addPage = () => {
          updateMeta('pages', [...pages, { page_number: pages.length + 1, statement_period: '', transactions: [] }]);
        };

        const updatePage = (pageIdx: number, field: string, value: string) => {
          const newPages = [...pages];
          newPages[pageIdx] = { ...newPages[pageIdx], [field]: value };
          updateMeta('pages', newPages);
        };

        const removePage = (pageIdx: number) => {
          const newPages = pages.filter((_: any, i: number) => i !== pageIdx)
                                .map((p: any, i: number) => ({ ...p, page_number: i + 1 }));
          updateMeta('pages', newPages);
        };

        const addTransaction = (pageIdx: number) => {
          const newPages = [...pages];
          const txs = newPages[pageIdx].transactions || [];
          newPages[pageIdx].transactions = [...txs, { date: '', description: '', amount: 0 }];
          updateMeta('pages', newPages);
        };

        const updateTransaction = (pageIdx: number, txIdx: number, field: string, value: string | number) => {
          const newPages = [...pages];
          newPages[pageIdx].transactions[txIdx] = { ...newPages[pageIdx].transactions[txIdx], [field]: value };
          updateMeta('pages', newPages);
        };

        const removeTransaction = (pageIdx: number, txIdx: number) => {
          const newPages = [...pages];
          newPages[pageIdx].transactions = newPages[pageIdx].transactions.filter((_: any, i: number) => i !== txIdx);
          updateMeta('pages', newPages);
        };

        return (
          <>




                Banking Institution
                 updateMeta('institution_name', e.target.value)} required />



                Account Holder
                 updateMeta('account_holder', e.target.value)} required />



                Account Number
                 updateMeta('account_number', e.target.value)} required />







                STATEMENT PAGES
                + Add Statement Page


              {pages.map((page: any, pageIdx: number) => (






                      Statement Period
                       updatePage(pageIdx, 'statement_period', e.target.value)} required />

                     removePage(pageIdx)} style={{ background: 'transparent', border: 'none', color: 'var(--accent-crimson)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontSize: '0.8rem' }}>REMOVE PAGE {page.page_number}






                      TRANSACTIONS
                       addTransaction(pageIdx)} style={{ background: 'transparent', border: '1px solid #aaa', color: '#aaa', padding: '2px 8px', borderRadius: '2px', cursor: 'pointer', fontSize: '0.7rem' }}>+ Add Row


                    {(page.transactions || []).map((tx: any, txIdx: number) => (


                         updateTransaction(pageIdx, txIdx, 'date', e.target.value)} style={{ width: '100px' }} required />
                         updateTransaction(pageIdx, txIdx, 'description', e.target.value)} style={{ flex: 1 }} required />
                         updateTransaction(pageIdx, txIdx, 'amount', parseFloat(e.target.value))} style={{ width: '120px' }} required />
                         removeTransaction(pageIdx, txIdx)} style={{ background: 'transparent', border: 'none', color: 'var(--accent-crimson)', cursor: 'pointer', fontSize: '1.2rem', padding: '0 0.5rem' }} title="Remove Row">×

                    ))}

                    {(!page.transactions || page.transactions.length === 0) && (


                        No transactions recorded on this page.

                    )}


              ))}

          </>
        );
      }

      case 'journal': {
        const pages = metadata.pages || [];

        const addPage = () => {
          updateMeta('pages', [...pages, { page_number: pages.length + 1, date_entry: '', content: '', is_torn: false }]);
        };

        const updatePage = (idx: number, field: string, value: any) => {
          const newPages = [...pages];
          newPages[idx] = { ...newPages[idx], [field]: value };
          updateMeta('pages', newPages);
        };

        const removePage = (idx: number) => {
          const newPages = pages.filter((_: any, i: number) => i !== idx)
                                .map((p: any, i: number) => ({ ...p, page_number: i + 1 }));
          updateMeta('pages', newPages);
        };

        return (
          <>




                Owner / Author
                 updateMeta('owner', e.target.value)} required />



                Cover Title (Optional)
                 updateMeta('cover_title', e.target.value)} placeholder="e.g., Personal Diary" />







                JOURNAL PAGES
                + Add Page


              {pages.map((page: any, idx: number) => (


                  PAGE {page.page_number}
                   removePage(idx)} style={{ position: 'absolute', top: '8px', right: '60px', background: 'transparent', border: 'none', color: 'var(--accent-crimson)', cursor: 'pointer', fontSize: '1.2rem' }}>×



                    Date Entry (Optional)
                     updatePage(idx, 'date_entry', e.target.value)} disabled={page.is_torn} />




                    Journal Content
                     updatePage(idx, 'content', e.target.value)} disabled={page.is_torn} required={!page.is_torn} />




                     updatePage(idx, 'is_torn', e.target.checked)} />
                    MARK AS TORN OUT (Hides content)


              ))}

          </>
        );
      }

      case 'contract': {
        const pages = metadata.pages || [];

        const addPage = () => {
          updateMeta('pages', [...pages, { page_number: pages.length + 1, terms_text: '', key_clause: '' }]);
        };

        const updatePage = (idx: number, field: string, value: string) => {
          const newPages = [...pages];
          newPages[idx] = { ...newPages[idx], [field]: value };
          updateMeta('pages', newPages);
        };

        const removePage = (idx: number) => {
          // Re-calculate page_number so they stay sequential
          const newPages = pages.filter((_: any, i: number) => i !== idx)
                                .map((p: any, i: number) => ({ ...p, page_number: i + 1 }));
          updateMeta('pages', newPages);
        };

        return (
          <>




                Parties Involved (Comma Separated)
                 updateMeta('parties_involved', e.target.value.split(',').map(s => s.trim()))}
                  placeholder="e.g., Vance Corp, Thorne LLC" required
                />




                Execution Date (Optional)
                 updateMeta('execution_date', e.target.value)}
                  placeholder="e.g., 14-OCT-2023"
                />







                CONTRACT PAGES
                + Add Page


              {pages.map((page: any, idx: number) => (


                  PAGE {page.page_number}
                   removePage(idx)} style={{ position: 'absolute', top: '8px', right: '60px', background: 'transparent', border: 'none', color: 'var(--accent-crimson)', cursor: 'pointer', fontSize: '1.2rem' }}>×



                    Terms and Conditions
                     updatePage(idx, 'terms_text', e.target.value)} style={{ minHeight: '100px' }} required />




                    Critical Clause (Gameplay Clue - Optional)
                     updatePage(idx, 'key_clause', e.target.value)} />


              ))}




               updateMeta('signatures_valid', e.target.checked)}
                style={{ transform: 'scale(1.5)' }}
              />

                SIGNATURES VALID (Uncheck to mark as Forged)


          </>
        );
      }

      case 'memo':
        return (
          <>




                Written By
                 updateMeta('written_by', e.target.value)}
                  required
                />




                Presentation Style
                 updateMeta('style', e.target.value)}
                >
                  Notebook Page
                  Sticky Note






              Memo Context
               updateMeta('context', e.target.value)}
                required
              />

          </>
        );

      case 'background_check':
        return (
          <>




                [ FORMATTING GUIDE ] You can use these HTML tags inside any of the text boxes below to trigger immersive investigative effects:



<span className="redacted">Text</span> : Renders a black redaction bar over the text.

<span className="highlighted">Text</span> : Applies a yellow highlighter marker effect.






Subject Name updateMeta('subject_name', e.target.value)} required />

DOB (e.g., 10/24/1985) updateMeta('dob', e.target.value)} required />

Sex/Age (e.g., M / 41) updateMeta('sex_age', e.target.value)} required />




Aliases / Monikers updateMeta('aliases', e.target.value)} />

Last Known Address updateMeta('last_known_address', e.target.value)} />



Employment & Financial Flags updateMeta('employment_financial', e.target.value)} style={{ minHeight: '80px' }} />

Criminal History (Docket Format) updateMeta('criminal_history', e.target.value)} style={{ minHeight: '100px' }} />

Known Associates updateMeta('associates', e.target.value)} style={{ minHeight: '80px' }} />



              Investigator Handwritten Scrawls
               updateMeta('investigator_notes', e.target.value)} placeholder="Will render in a red cursive marker font across the bottom of the page..." style={{ minHeight: '80px' }} />

          </>
        );

      default:
        // Legacy or un-typed fallback
        if (evidenceType === 'testimony') {
          return (


              Official Transcript
               updateMeta('transcript', e.target.value)} />

          );
        }
        return null;
    }
  };

  if (evidenceType === 'image' || evidenceType === 'audio') return null;

  return (




        [ Structured Metadata Injection ]


      {renderSubTypeSelector()}

      {(subType || evidenceType === 'testimony') && (


          {renderDynamicInputs()}

      )}

  );
}

export interface ChoiceOutcomes {
  feedback: string;
  next_question_id: number | null;
  gives_strike: boolean;
  unlock_evidence: number[];
  unlock_levels: number[];
  unlock_suspects: number[];
  unlock_victims: number[];
}

export interface ChoiceRequirements {
  required_evidence: number[];
  required_choices: number[];
}

export const defaultRequirements = (): ChoiceRequirements => ({ required_evidence: [], required_choices: [] });

export const defaultOutcomes = (): ChoiceOutcomes => ({
  feedback: '', next_question_id: null, gives_strike: false,
  unlock_evidence: [], unlock_levels: [], unlock_suspects: [], unlock_victims: [],
});

const appendToFormData = (fd: FormData, rootKey: string, obj: any) => {
  if (obj === null || obj === undefined) return;
  if (Array.isArray(obj)) {
      obj.forEach((val, i) => appendToFormData(fd, `${rootKey}[${i}]`, val));
  } else if (typeof obj === 'object' && !(obj instanceof File)) {
      Object.keys(obj).forEach(key => appendToFormData(fd, `${rootKey}[${key}]`, obj[key]));
  } else {
      fd.append(rootKey, obj instanceof File ? obj : obj.toString());
  }
};

export const appendChoicesToFormData = (formData: FormData, choices: any[]) => {
  for (let i = 0; i < choices.length; i++) {
    const choice = choices[i];
    formData.append(`choices[${i}][text]`, choice.text);

    const cleanReqs: any = {};
    if (choice.requirements?.required_evidence?.length > 0) cleanReqs.required_evidence = choice.requirements.required_evidence.map(Number);
    if (choice.requirements?.required_choices?.length > 0) cleanReqs.required_choices = choice.requirements.required_choices.map(Number);
    if (Object.keys(cleanReqs).length > 0) appendToFormData(formData, `choices[${i}][requirements]`, cleanReqs);

    const cleanOutcomes: any = {};
    if (choice.outcomes?.gives_strike) cleanOutcomes.gives_strike = true;
    if (choice.outcomes?.feedback?.trim()) cleanOutcomes.feedback = choice.outcomes.feedback.trim();
    if (choice.outcomes?.next_question_id) cleanOutcomes.next_question_id = Number(choice.outcomes.next_question_id);
    if (choice.outcomes?.unlock_evidence?.length > 0) cleanOutcomes.unlock_evidence = choice.outcomes.unlock_evidence.map(Number);
    if (choice.outcomes?.unlock_levels?.length > 0) cleanOutcomes.unlock_levels = choice.outcomes.unlock_levels.map(Number);
    if (choice.outcomes?.unlock_suspects?.length > 0) cleanOutcomes.unlock_suspects = choice.outcomes.unlock_suspects.map(Number);
    if (choice.outcomes?.unlock_victims?.length > 0) cleanOutcomes.unlock_victims = choice.outcomes.unlock_victims.map(Number);
    if (Object.keys(cleanOutcomes).length > 0) appendToFormData(formData, `choices[${i}][outcomes]`, cleanOutcomes);
  }
};

interface NodePayload {
  level_id: string;
  text: string;
  store_locally: boolean;
  choices: any[];
  image?: File | null;
  audio?: File | null;
}

export const buildNodeFormData = (payload: NodePayload): FormData => {
  const formData = new FormData();
  formData.append('level_id', payload.level_id);
  formData.append('text', payload.text);
  formData.append('store_locally', payload.store_locally ? '1' : '0');

  if (payload.image) formData.append('image', payload.image);
  if (payload.audio) formData.append('audio', payload.audio);

  appendChoicesToFormData(formData, payload.choices);

  return formData;
};

